/// Builds a [`AstType::TheoryAtomDefinition`] node.
///
/// The arguments follow clingo's constructor table for the type, in order:
///
/// - `location`: [`Attribute::Location`], a `&Span`.
/// - `atom_type`: [`Attribute::AtomType`], a `TheoryAtomType`.
/// - `name`: [`Attribute::Name`], a `&str`.
/// - `arity`: [`Attribute::Arity`], a `i32`.
/// - `term`: [`Attribute::Term`], a `&str`.
/// - `guard`: [`Attribute::Guard`], a `Option<&Ast>`.
///
/// Every node argument is borrowed: the new node holds its own reference, and
/// the caller's handles stay valid. The result is a new top node, and shares
/// its children with the arguments. What kind of node an argument is is not
/// checked.
///
/// # Errors
///
/// - [`ErrorKind::InvalidInput`] if `arity` is negative;
/// - [`ErrorKind::Nul`] if a string contains a NUL byte;
/// - [`ErrorKind::BadAlloc`] if clingo runs out of memory.
///
/// A huge arity is accepted, because it is clingo's own limit: adding a
/// `project_signature` with an arity in the hundreds of millions to a program
/// makes clingo allocate one variable per argument until memory runs out
/// (UPSTREAM-ISSUES U48), as the text `#project p/4294967295.` does.
pub fn theory_atom_definition(
    location: &Span,
    atom_type: TheoryAtomType,
    name: &str,
    arity: i32,
    term: &str,
    guard: Option<&Ast>,
) -> Result<Ast> {
    if arity < 0 {
        return Err(
            Error::new(
                ErrorKind::InvalidInput,
                format!("{arity} is not an arity, which is at least 0"),
            ),
        );
    }
    raw::ast_build(
            AstType::TheoryAtomDefinition,
            &[
                BuildArg::Span(location),
                BuildArg::Number(i32::from(atom_type)),
                BuildArg::Str(name),
                BuildArg::Number(arity),
                BuildArg::Str(term),
                BuildArg::OptionalAst(guard),
            ],
        )
        .map(Ast::from_raw)
        .map_err(|e| e.context("building a `theory_atom_definition` node"))
}
