/// The values a `number` attribute may take on a node of a given type.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum NumberDomain {
    /// Any `i32`.
    Any,
    /// A boolean, stored as 0 or 1.
    Bool,
    /// `0..=max`: an enum's constants, or `0..=i32::MAX` for an arity.
    Range(i32),
}
/// The domain of `attribute` on a node of type `kind` (`set_number`).
pub(crate) fn number_domain(kind: AstType, attribute: Attribute) -> NumberDomain {
    match (kind, attribute) {
        (AstType::UnaryOperation, Attribute::OperatorType) => NumberDomain::Range(2),
        (AstType::BinaryOperation, Attribute::OperatorType) => NumberDomain::Range(8),
        (AstType::Function, Attribute::External) => NumberDomain::Bool,
        (AstType::BooleanConstant, Attribute::Value) => NumberDomain::Bool,
        (AstType::Guard, Attribute::Comparison) => NumberDomain::Range(5),
        (AstType::BodyAggregate, Attribute::Function) => NumberDomain::Range(4),
        (AstType::HeadAggregate, Attribute::Function) => NumberDomain::Range(4),
        (AstType::TheorySequence, Attribute::SequenceType) => NumberDomain::Range(2),
        (AstType::Literal, Attribute::Sign) => NumberDomain::Range(2),
        (AstType::TheoryOperatorDefinition, Attribute::OperatorType) => {
            NumberDomain::Range(2)
        }
        (AstType::TheoryAtomDefinition, Attribute::AtomType) => NumberDomain::Range(3),
        (AstType::TheoryAtomDefinition, Attribute::Arity) => {
            NumberDomain::Range(i32::MAX)
        }
        (AstType::Definition, Attribute::IsDefault) => NumberDomain::Bool,
        (AstType::ShowSignature, Attribute::Arity) => NumberDomain::Range(i32::MAX),
        (AstType::ShowSignature, Attribute::Positive) => NumberDomain::Bool,
        (AstType::ProjectSignature, Attribute::Arity) => NumberDomain::Range(i32::MAX),
        (AstType::ProjectSignature, Attribute::Positive) => NumberDomain::Bool,
        (AstType::Defined, Attribute::Arity) => NumberDomain::Range(i32::MAX),
        (AstType::Defined, Attribute::Positive) => NumberDomain::Bool,
        (AstType::Comment, Attribute::CommentType) => NumberDomain::Range(1),
        _ => NumberDomain::Any,
    }
}
/// The attributes of `kind` that hold nodes, in constructor order.
pub(crate) fn child_attributes(kind: AstType) -> &'static [(Attribute, AttributeType)] {
    match kind {
        AstType::UnaryOperation => &[(Attribute::Argument, AttributeType::Ast)],
        AstType::BinaryOperation => {
            &[
                (Attribute::Left, AttributeType::Ast),
                (Attribute::Right, AttributeType::Ast),
            ]
        }
        AstType::Interval => {
            &[
                (Attribute::Left, AttributeType::Ast),
                (Attribute::Right, AttributeType::Ast),
            ]
        }
        AstType::Function => &[(Attribute::Arguments, AttributeType::AstArray)],
        AstType::Pool => &[(Attribute::Arguments, AttributeType::AstArray)],
        AstType::SymbolicAtom => &[(Attribute::Symbol, AttributeType::Ast)],
        AstType::Comparison => {
            &[
                (Attribute::Term, AttributeType::Ast),
                (Attribute::Guards, AttributeType::AstArray),
            ]
        }
        AstType::Guard => &[(Attribute::Term, AttributeType::Ast)],
        AstType::ConditionalLiteral => {
            &[
                (Attribute::Literal, AttributeType::Ast),
                (Attribute::Condition, AttributeType::AstArray),
            ]
        }
        AstType::Aggregate => {
            &[
                (Attribute::LeftGuard, AttributeType::OptionalAst),
                (Attribute::Elements, AttributeType::AstArray),
                (Attribute::RightGuard, AttributeType::OptionalAst),
            ]
        }
        AstType::BodyAggregateElement => {
            &[
                (Attribute::Terms, AttributeType::AstArray),
                (Attribute::Condition, AttributeType::AstArray),
            ]
        }
        AstType::BodyAggregate => {
            &[
                (Attribute::LeftGuard, AttributeType::OptionalAst),
                (Attribute::Elements, AttributeType::AstArray),
                (Attribute::RightGuard, AttributeType::OptionalAst),
            ]
        }
        AstType::HeadAggregateElement => {
            &[
                (Attribute::Terms, AttributeType::AstArray),
                (Attribute::Condition, AttributeType::Ast),
            ]
        }
        AstType::HeadAggregate => {
            &[
                (Attribute::LeftGuard, AttributeType::OptionalAst),
                (Attribute::Elements, AttributeType::AstArray),
                (Attribute::RightGuard, AttributeType::OptionalAst),
            ]
        }
        AstType::Disjunction => &[(Attribute::Elements, AttributeType::AstArray)],
        AstType::TheorySequence => &[(Attribute::Terms, AttributeType::AstArray)],
        AstType::TheoryFunction => &[(Attribute::Arguments, AttributeType::AstArray)],
        AstType::TheoryUnparsedTermElement => &[(Attribute::Term, AttributeType::Ast)],
        AstType::TheoryUnparsedTerm => &[(Attribute::Elements, AttributeType::AstArray)],
        AstType::TheoryGuard => &[(Attribute::Term, AttributeType::Ast)],
        AstType::TheoryAtomElement => {
            &[
                (Attribute::Terms, AttributeType::AstArray),
                (Attribute::Condition, AttributeType::AstArray),
            ]
        }
        AstType::TheoryAtom => {
            &[
                (Attribute::Term, AttributeType::Ast),
                (Attribute::Elements, AttributeType::AstArray),
                (Attribute::Guard, AttributeType::OptionalAst),
            ]
        }
        AstType::Literal => &[(Attribute::Atom, AttributeType::Ast)],
        AstType::TheoryTermDefinition => {
            &[(Attribute::Operators, AttributeType::AstArray)]
        }
        AstType::TheoryAtomDefinition => {
            &[(Attribute::Guard, AttributeType::OptionalAst)]
        }
        AstType::Rule => {
            &[
                (Attribute::Head, AttributeType::Ast),
                (Attribute::Body, AttributeType::AstArray),
            ]
        }
        AstType::Definition => &[(Attribute::Value, AttributeType::Ast)],
        AstType::ShowTerm => {
            &[
                (Attribute::Term, AttributeType::Ast),
                (Attribute::Body, AttributeType::AstArray),
            ]
        }
        AstType::Minimize => {
            &[
                (Attribute::Weight, AttributeType::Ast),
                (Attribute::Priority, AttributeType::Ast),
                (Attribute::Terms, AttributeType::AstArray),
                (Attribute::Body, AttributeType::AstArray),
            ]
        }
        AstType::Program => &[(Attribute::Parameters, AttributeType::AstArray)],
        AstType::External => {
            &[
                (Attribute::Atom, AttributeType::Ast),
                (Attribute::Body, AttributeType::AstArray),
                (Attribute::ExternalType, AttributeType::Ast),
            ]
        }
        AstType::Edge => {
            &[
                (Attribute::NodeU, AttributeType::Ast),
                (Attribute::NodeV, AttributeType::Ast),
                (Attribute::Body, AttributeType::AstArray),
            ]
        }
        AstType::Heuristic => {
            &[
                (Attribute::Atom, AttributeType::Ast),
                (Attribute::Body, AttributeType::AstArray),
                (Attribute::Bias, AttributeType::Ast),
                (Attribute::Priority, AttributeType::Ast),
                (Attribute::Modifier, AttributeType::Ast),
            ]
        }
        AstType::ProjectAtom => {
            &[
                (Attribute::Atom, AttributeType::Ast),
                (Attribute::Body, AttributeType::AstArray),
            ]
        }
        AstType::TheoryDefinition => {
            &[
                (Attribute::Terms, AttributeType::AstArray),
                (Attribute::Atoms, AttributeType::AstArray),
            ]
        }
        _ => &[],
    }
}
/// Rewrites a syntax tree: one method per node type, each defaulting to
/// [`walk`], which visits the node's children.
///
/// Every method takes a borrowed node and returns an owned one. Returning
/// a clone of the argument means "unchanged"; returning any other node
/// replaces it, and the replacement may be of a different type. A child
/// counts as changed exactly when the node returned for it is not
/// [`Ast::ptr_eq`] to the original (identity, as pyclingo's `is not`), so
/// an unchanged subtree is shared, not copied, and [`walk`] returns the
/// very node it was given when nothing below it changed.
///
/// The first error any method returns stops the whole walk and is returned
/// unchanged. The original tree is never modified by `walk`, also on an
/// error.
///
/// A visitor must not edit the tree it walks, whether through a setter on
/// the node it was given or on one of its children: [`walk`] reads the
/// children as it goes, so the result of such an edit is a silently
/// partial rewrite. Nothing is unsafe about it (every index is checked),
/// but it is not the tree you meant. Edit a `copy()` instead.
///
/// `visit` dispatches on the node's type and should not be overridden.
/// The trait is object safe: `&mut dyn Visitor` works.
///
/// # Deleting and inserting array elements
///
/// [`walk`] replaces array elements one for one, as pyclingo's
/// `Transformer` does by default. To delete or insert elements, call
/// [`walk`] and edit the result, but `copy()` it first when it is
/// [`Ast::ptr_eq`] to the input: nothing below it changed, so it *is* the
/// original node, and editing it would edit the original tree.
///
/// ```
/// use clingox::ast::{self, Ast, AstType, Attribute, Visitor, walk};
/// use clingox::Result;
///
/// /// Drops the first body literal of every rule.
/// struct DropFirst;
///
/// impl Visitor for DropFirst {
///     fn visit_rule(&mut self, node: &Ast) -> Result<Ast> {
///         let walked = walk(self, node)?;
///         let edited = if walked.ptr_eq(node) { walked.copy()? } else { walked };
///         if edited.ast_array_len(Attribute::Body)? > 0 {
///             edited.delete_ast_at(Attribute::Body, 0)?;
///         }
///         Ok(edited)
///     }
/// }
///
/// let mut rules = Vec::new();
/// ast::parse_string("h :- a, b.", |node| {
///     if node.ast_type() == AstType::Rule {
///         rules.push(node);
///     }
///     Ok(())
/// })?;
