/// Visits the children of `node` through `visitor` and rebuilds `node` when
/// any of them changed.
///
/// For each child attribute of the node's type, in constructor order:
/// an `ast` attribute is visited, an `optional_ast` is skipped when it is
/// `None` and visited otherwise, and every element of an `ast_array` is
/// visited in index order, one replacement per element (the length cannot
/// change here). Other attributes (`location`, names, symbols, numbers,
/// strings) are never visited.
///
/// If no child changed, the result is a clone of `node`, so it is
/// [`Ast::ptr_eq`] to it and nothing is allocated. Otherwise the result is
/// `node.copy()` with only the changed children replaced: unchanged
/// children and siblings stay shared with the original, and every other
/// attribute, the location included, is kept. The original is never
/// modified.
///
/// An override can call `walk` before or after its own edits. See
/// [`Visitor`] for how to delete or insert array elements.
///
/// # Stack use
///
/// `walk` recurses once per level of the tree, through
/// [`Visitor::visit`], like pyclingo's `Transformer`, and has no depth
/// limit of its own. A tree deep enough to exhaust the thread's stack
/// overflows it. Printing, comparing and dropping such a tree recurse in
/// clingo the same way, so a tree that clingo itself can print on a
/// thread can also be walked on it; run a visitor over very deep trees on
/// a thread with a large stack.
///
/// # Errors
///
/// The first error any `visit_*` method, setter or `copy` reports, which
/// is returned unchanged.
pub fn walk<V: Visitor + ?Sized>(visitor: &mut V, node: &Ast) -> Result<Ast> {
    let mut rebuilt: Option<Ast> = None;
    for &(attribute, kind) in child_attributes(node.ast_type()) {
        match kind {
            AttributeType::Ast => {
                let child = node.ast(attribute)?;
                let visited = visitor.visit(&child)?;
                if !visited.ptr_eq(&child) {
                    copy_of(&mut rebuilt, node)?.set_ast_fresh(attribute, &visited)?;
                }
            }
            AttributeType::OptionalAst => {
                if let Some(child) = node.optional_ast(attribute)? {
                    let visited = visitor.visit(&child)?;
                    if !visited.ptr_eq(&child) {
                        copy_of(&mut rebuilt, node)?
                            .set_optional_ast_fresh(attribute, &visited)?;
                    }
                }
            }
            AttributeType::AstArray => {
                for index in 0..node.ast_array_len(attribute)? {
                    let child = node.ast_at(attribute, index)?;
                    let visited = visitor.visit(&child)?;
                    if !visited.ptr_eq(&child) {
                        copy_of(&mut rebuilt, node)?
                            .set_ast_at_fresh(attribute, index, &visited)?;
                    }
                }
            }
            _ => {}
        }
    }
    Ok(rebuilt.unwrap_or_else(|| node.clone()))
}
/// The private copy `walk` edits: made on the first change, and a handle to
/// the same node afterwards.
///
/// This is why `walk` may use the setters that skip the cycle check: the copy
/// is new, and only `walk` holds a handle to it until `walk` returns. A
/// replacement a visitor returns was made before the copy could be reached,
/// so it cannot reach the copy, and adding it below the copy cannot close a
/// cycle. The original tree is only read.
fn copy_of(rebuilt: &mut Option<Ast>, node: &Ast) -> Result<Ast> {
    if let Some(copy) = rebuilt {
        return Ok(copy.clone());
    }
    let copy = node.copy()?;
    *rebuilt = Some(copy.clone());
    Ok(copy)
}
